// Flux « restaurateur » — généré par @velekya/n8n-flows (pnpm -F @velekya/n8n-flows build:flows).
// Ne pas modifier ici : modifier packages/n8n-flows/src puis régénérer.

/**
 * Briques communes aux flux métier. Ce fichier est recopié tel quel (après
 * compilation) dans le nœud Code de chaque flux n8n : il ne doit RIEN importer
 * à l'exécution, et n'utiliser que ce qu'offre Node (Intl compris).
 *
 * Le contrat (corps reçu, réponses possibles) est celui de
 * `docs/n8n/README.md` et de `apps/api/src/assistants/runtime/n8n.runtime.ts`.
 */
const MAX_TEXT = 1600;
const MAX_SUMMARY = 300;
function reply(text, summary, capability = "questions") {
    return { kind: "reply", text: cut(text, MAX_TEXT), capability, summary: cut(summary, MAX_SUMMARY) };
}
function escalate(question, context, ackText, summary) {
    return {
        kind: "escalate",
        question: cut(question, MAX_TEXT),
        context: cut(context, MAX_TEXT),
        ackText: cut(ackText, MAX_TEXT),
        summary: cut(summary, MAX_SUMMARY),
    };
}
function appointment(text, summary, slotISO, status = "propose") {
    return { kind: "appointment", text: cut(text, MAX_TEXT), summary: cut(summary, MAX_SUMMARY), slotISO, status };
}
/** Un bouton absent est considéré allumé : seul `false` coupe une capacité. */
function switchOn(req, key) {
    return req.switches?.[key] !== false;
}
/** Vrai si le corps reçu a la forme attendue (version 2 du contrat). */
function isValidRequest(req) {
    if (!req || typeof req !== "object")
        return false;
    const r = req;
    return (r.version === 2 &&
        typeof r.text === "string" &&
        r.text.trim().length > 0 &&
        !!r.assistant &&
        typeof r.assistant === "object");
}
// ── Texte ────────────────────────────────────────────────────────────────────
/** Minuscules, sans accents ; apostrophes et traits d'union deviennent des espaces. */
function norm(s) {
    return s
        .toLowerCase()
        .normalize("NFD")
        .replace(/[̀-ͯ]/g, "")
        .replace(/['’-]/g, " ")
        .replace(/\s+/g, " ")
        .trim();
}
/**
 * Vrai si le texte (déjà normalisé) contient l'un des mots ou expressions en
 * début de mot : « douloureu » couvre « douloureuse », « bus » ne se
 * déclenche pas sur « abus ».
 */
function has(t, words) {
    return words.some((w) => {
        const i = t.indexOf(w);
        if (i < 0)
            return false;
        for (let at = i; at >= 0; at = t.indexOf(w, at + 1)) {
            if (at === 0 || !/[a-z0-9]/.test(t[at - 1]))
                return true;
        }
        return false;
    });
}
/**
 * Demande de prix (texte déjà normalisé). Le flux répond lui-même : l'API ne
 * filtre plus les prix avant un flux générique de métier. Comme l'ancien
 * garde-fou, une demande de rendez-vous ou de réservation passe avant.
 * « Combien de temps / de personnes » n'est pas une question de prix.
 */
const PRICE = [
    "prix", "tarif", "coute", "couter", "coutent", "cout ", "combien ca", "combien cela", "combien pour",
    "combien coute", "combien vous prenez", "combien je vous dois", "combien est ce", "combien faut il",
    "c est combien", "ca fait combien", "ca revient a combien", "a combien",
];
const BOOKING_HINT = [
    "rendez vous", "rdv", "reserver", "reservation", "creneau", "disponibilite", "prendre date",
    "une table", "je voudrais venir", "passer vous voir",
];
function asksPrice(t) {
    const s = `${t} `;
    return has(s, PRICE) && !has(s, BOOKING_HINT);
}
function cut(s, max) {
    const t = s.trim();
    return t.length > max ? `${t.slice(0, max - 1)}…` : t;
}
function clip(s) {
    return cut(s.replace(/\s+/g, " "), 180);
}
function sentence(s) {
    const t = s.trim();
    return /[.!?]$/.test(t) ? t : `${t}.`;
}
/** Oui / non tels que saisis au « premier jour ». null si non renseigné. */
function yesNo(v) {
    const t = norm(v ?? "");
    if (["oui", "yes", "true", "1"].includes(t))
        return true;
    if (["non", "no", "false", "0"].includes(t))
        return false;
    return null;
}
/** Valeur d'une spécificité dont la clé contient l'un des mots donnés. */
function pickSpecific(specifics, keys) {
    for (const [k, v] of Object.entries(specifics ?? {})) {
        if (typeof v === "string" && v.trim() && keys.some((key) => norm(k).includes(key)))
            return v.trim();
    }
    return null;
}
/** Découpe une liste saisie librement (« Dr Martin, Dr Roy » ou une par ligne). */
function splitList(v) {
    return (v ?? "")
        .split(/[\n,;•]+|\s+et\s+/)
        .map((s) => s.trim().replace(/^[-*]\s*/, ""))
        .filter((s) => s.length > 1);
}
const STOPWORDS = new Set([
    "quand", "pour", "avec", "dans", "cette", "vous", "nous", "elle", "leur", "leurs", "sont",
    "faire", "demande", "demandent", "repond", "reponds", "repondre", "toujours", "jamais",
    "client", "clients", "patient", "patients", "bonjour", "merci", "est", "votre", "notre",
]);
/** Consigne du patron qui partage au moins deux mots porteurs avec le message. */
function matchInstruction(instructions, message) {
    const msg = norm(message);
    for (const instruction of instructions ?? []) {
        const words = [
            ...new Set(norm(instruction)
                .split(/[^a-z0-9]+/)
                .filter((w) => w.length >= 4 && !STOPWORDS.has(w))),
        ];
        if (words.filter((w) => msg.includes(w)).length >= 2)
            return instruction;
    }
    return null;
}
// ── Dates (heure de Paris) ───────────────────────────────────────────────────
const PARIS = "Europe/Paris";
const FR_DAYS = ["dimanche", "lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi"];
const FR_MONTHS = [
    "janvier", "fevrier", "mars", "avril", "mai", "juin",
    "juillet", "aout", "septembre", "octobre", "novembre", "decembre",
];
const FR_MONTHS_LABEL = [
    "janvier", "février", "mars", "avril", "mai", "juin",
    "juillet", "août", "septembre", "octobre", "novembre", "décembre",
];
function parisParts(date) {
    const f = new Intl.DateTimeFormat("en-GB", {
        timeZone: PARIS,
        year: "numeric",
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
        hourCycle: "h23",
    });
    const p = {};
    for (const part of f.formatToParts(date))
        p[part.type] = part.value;
    return { y: Number(p.year), m: Number(p.month), d: Number(p.day), h: Number(p.hour), min: Number(p.minute) };
}
/** Heure locale de Paris → instant ISO (UTC), changements d'heure compris. */
function parisToISO(day, h, min) {
    const guess = Date.UTC(day.y, day.m - 1, day.d, h, min);
    const p = parisParts(new Date(guess));
    const offset = Date.UTC(p.y, p.m - 1, p.d, p.h, p.min) - guess;
    return new Date(guess - offset).toISOString();
}
function addDays(day, n) {
    const t = new Date(Date.UTC(day.y, day.m - 1, day.d + n));
    return { y: t.getUTCFullYear(), m: t.getUTCMonth() + 1, d: t.getUTCDate() };
}
function weekdayOf(day) {
    return new Date(Date.UTC(day.y, day.m - 1, day.d)).getUTCDay();
}
function cmpDay(a, b) {
    return Date.UTC(a.y, a.m - 1, a.d) - Date.UTC(b.y, b.m - 1, b.d);
}
/** « jeudi 20 novembre » */
function humanDay(day) {
    return `${FR_DAYS[weekdayOf(day)]} ${day.d === 1 ? "1er" : day.d} ${FR_MONTHS_LABEL[day.m - 1]}`;
}
/** « 9h », « 14h30 » */
function humanTime(time) {
    return `${time.h}h${time.min ? String(time.min).padStart(2, "0") : ""}`;
}
/** Repère un jour, une heure et un moment de la journée (heure de Paris). */
function parseSlot(text, now) {
    const t = norm(text);
    const nowP = parisParts(now);
    const today = { y: nowP.y, m: nowP.m, d: nowP.d };
    let part = null;
    if (/\b(apres midi|aprem|cet apres midi)\b/.test(t))
        part = "apres-midi";
    else if (/\b(matin|matinee)\b/.test(t))
        part = "matin";
    else if (/\b(soir|soiree|fin de journee)\b/.test(t))
        part = "soir";
    // Jour : date explicite d'abord, puis mots relatifs, puis jour de semaine.
    let day = null;
    const withYear = (d, m) => {
        if (m < 1 || m > 12 || d < 1 || d > 31)
            return null;
        const candidate = { y: today.y, m, d };
        return cmpDay(candidate, today) < 0 ? { y: today.y + 1, m, d } : candidate;
    };
    const numeric = t.match(/\b(\d{1,2})\s*\/\s*(\d{1,2})\b/);
    const named = t.match(new RegExp(`\\b(1er|\\d{1,2})\\s+(${FR_MONTHS.join("|")})\\b`));
    const bare = t.match(/\b(?:le|du|ce)\s+(1er|\d{1,2})\b(?!\s*(?:h|heures?|:|\/|\d))/);
    if (numeric) {
        day = withYear(Number(numeric[1]), Number(numeric[2]));
    }
    else if (named) {
        day = withYear(named[1] === "1er" ? 1 : Number(named[1]), FR_MONTHS.indexOf(named[2]) + 1);
    }
    else if (/\bapres demain\b/.test(t)) {
        day = addDays(today, 2);
    }
    else if (/\bdemain\b/.test(t)) {
        day = addDays(today, 1);
    }
    else if (/\b(aujourd hui|ce matin|ce midi|ce soir|cet apres midi|tout a l heure)\b/.test(t)) {
        day = today;
    }
    else {
        const idx = FR_DAYS.findIndex((d) => new RegExp(`\\b${d}\\b`).test(t));
        if (idx >= 0) {
            let delta = (idx - weekdayOf(today) + 7) % 7;
            if (delta === 0)
                delta = 7;
            day = addDays(today, delta);
        }
        else if (bare) {
            const d = bare[1] === "1er" ? 1 : Number(bare[1]);
            // « le 3 » : ce mois-ci, ou le mois suivant si la date est passée.
            const thisMonth = { y: today.y, m: today.m, d };
            day =
                d >= 1 && d <= 31
                    ? cmpDay(thisMonth, today) >= 0
                        ? thisMonth
                        : today.m === 12
                            ? { y: today.y + 1, m: 1, d }
                            : { y: today.y, m: today.m + 1, d }
                    : null;
        }
    }
    // Heure : « 14h », « 14h30 », « 14:30 », « 9 heures », « à midi ».
    let time = null;
    const tm = t.match(/\b(\d{1,2})\s*(?:h|heures?|:)\s*(\d{2})?\b/);
    if (tm) {
        let h = Number(tm[1]);
        const min = tm[2] ? Number(tm[2]) : 0;
        if ((part === "apres-midi" || part === "soir") && h >= 1 && h < 12)
            h += 12;
        if (h >= 0 && h <= 23 && min >= 0 && min <= 59)
            time = { h, min };
    }
    else if (/\ba midi\b/.test(t)) {
        time = { h: 12, min: 0 };
    }
    return { day, time, part };
}
/** Vrai si le jour (et l'heure, si donnée) est déjà passé. */
function isPast(slot, now) {
    if (!slot.day)
        return false;
    const p = parisParts(now);
    const c = cmpDay(slot.day, { y: p.y, m: p.m, d: p.d });
    if (c !== 0)
        return c < 0;
    return slot.time ? slot.time.h * 60 + slot.time.min <= p.h * 60 + p.min : false;
}

/**
 * Flux générique « Restaurant » (prêt à l'emploi, Lot 16).
 *
 * Partagé par tous les restaurants abonnés : tout ce qui est propre au
 * restaurant arrive dans la requête (établissement, spécificités du « premier
 * jour », consignes, boutons). Rien n'est stocké ici.
 *
 * Principe : il répond quand il est sûr, sinon il transmet au restaurant. Le
 * cahier de réservations n'est pas consulté : une réservation est NOTÉE
 * (`propose`) et le restaurant la confirme. Il ne garantit jamais l'absence
 * d'un allergène, n'accepte pas un groupe au-delà de la taille fixée, ne
 * promet pas de plat hors carte et ne négocie pas.
 *
 * Spécificités lues (catalogue, `personalization`) : `capacite`, `horaires`,
 * `carte`, `groupes_max`.
 * Boutons lus : `reservations` (absent = allumé), `complet` (absent = éteint :
 * seul `true` dit que le restaurant est complet aujourd'hui). Libellés par
 * défaut dans `apps/api/prisma/seed-data/catalog.ts`.
 */

const COMPLAINT = [
    "plainte", "reclamation", "reclamer", "intoxication", "intoxique", "malade apres", "tombe malade",
    "j ai ete malade", "on a ete malades", "nous avons ete malades", "decu", "decue", "decevant", "inadmissible",
    "scandaleux", "rembourser", "remboursement", "cheveu dans", "pas frais", "avis negatif", "mauvais accueil",
];
const CANCEL = [
    "annuler", "annulation", "decommander", "ne pourrons pas venir", "ne pourrai pas venir", "ne pourra pas venir",
    "ne pouvons plus venir", "ne peux plus venir", "empeche",
];
const MOVE = [
    "decaler", "deplacer", "reporter", "changer ma reservation", "changer la reservation", "modifier ma reservation",
    "modifier la reservation", "changer l heure", "changer le nombre", "ajouter une personne",
    "ajouter deux personnes",
];
const PRIVATE_EVENT = [
    "privatis", "seminaire", "mariage", "bapteme", "communion", "enterrement de vie",
    "repas d entreprise", "repas de groupe", "comite d entreprise", "cocktail", "traiteur",
];
const BOOK = [
    "reserver", "reservation", "une table", "la table", "des tables", "table pour", "table de", "couverts",
    "place pour", "de la place", "venir manger", "venir diner", "venir dejeuner", "manger ce", "diner ce",
    "dejeuner ce",
];
const WAITLIST = ["liste d attente", "si une table se libere", "si une place se libere", "en cas de desistement"];
const ALLERGY = [
    "allerg", "intoleran", "sans gluten", "gluten", "celiaque", "lactose", "sans lait", "arachide", "cacahuete",
    "fruits a coque", "noix", "fruits de mer", "crustace", "oeuf", "sesame", "vegan", "vegetalien",
    "vegetarien", "halal", "casher", "kasher", "sans porc",
];
const HOURS = [
    "horaire", "ouvert", "ouverte", "ouverts", "ferme", "fermes", "quelle heure", "jusqu a quelle heure",
    "a partir de quelle heure", "service du", "dernier service", "derniere commande",
];
const ADDRESS = ["adresse", "ou etes vous", "ou se trouve", "comment venir", "parking", "garer", "vous situer", "acces", "metro", "bus", "tram"];
/** Tournures parlées (« c'est où ? ») — mot entier, pour ne pas lire « c'est ouvert ». */
const ADDRESS_RE = /\b(c est ou|ou est (le|votre|ce) restaurant|ou est situe|ou ca se trouve|situe ou)\b/;
const asksAddress = (t) => has(t, ADDRESS) || ADDRESS_RE.test(t);
const MENU = [
    "carte", "menu", "plat du jour", "plats", "specialite", "qu est ce que vous servez", "que servez vous",
    "formule", "dessert", "boissons", "vins",
];
const PAYMENT = [
    "carte bancaire", "carte bleue", "cb", "ticket resto", "tickets resto", "titre restaurant", "titres restaurant",
    "cheque", "especes", "paiement", "payer", "carte cadeau", "bon cadeau",
];
const TAKEAWAY = ["a emporter", "emporter", "livraison", "livrez", "livrer", "click and collect", "uber", "deliveroo"];
const DISCOUNT = ["remise", "reduction", "promo", "geste commercial", "ristourne", "moins cher", "offert"];
const NUMBER_WORDS = {
    un: 1, une: 1, deux: 2, trois: 3, quatre: 4, cinq: 5, six: 6, sept: 7, huit: 8, neuf: 9, dix: 10,
    onze: 11, douze: 12, treize: 13, quatorze: 14, quinze: 15, seize: 16, vingt: 20, trente: 30,
};
const NUM = `(\\d{1,3}|${Object.keys(NUMBER_WORDS).join("|")})`;
/** Un nombre suivi d'une heure (« pour 20h », « à 8 heures ») n'est pas un nombre de personnes. */
const NOT_TIME = `(?!\\s*(?:h\\b|h\\d|heures?\\b|:|\\/))`;
const SIZE_PATTERNS = [
    new RegExp(`\\b${NUM}\\s*(?:personnes?|pers|couverts?|adultes?|convives?)\\b`),
    new RegExp(`\\btable (?:pour|de) ${NUM}\\b${NOT_TIME}`),
    new RegExp(`\\b(?:pour|sommes|serons|sera|seront|etre) ${NUM}\\b${NOT_TIME}`),
    /\ba (deux|trois|quatre|cinq|six|sept|huit|neuf|dix)\b(?!\s*heures?)/,
    // « venir dîner à 6 » : un verbe d'abord, sinon « à 8 » serait une heure.
    new RegExp(`\\b(?:venir|viendr[a-z]*|manger|diner|dejeuner|etre) a ${NUM}\\b${NOT_TIME}`),
];
/** Questions par lesquelles il fait avancer une réservation. */
const BOOKING_QUESTION = /combien de personnes|quel jour|quelle heure|a quel nom/;
const ASKED_NAME = /a quel nom/;
function handle(req, now) {
    if (!isValidRequest(req)) {
        return escalate("Un message n'a pas pu être lu.", "Le message est arrivé dans un format inattendu.", "Merci pour votre message. Je le transmets au restaurant, qui vous répond très vite.", "Message transmis au restaurant.");
    }
    const a = req.assistant;
    const sp = a.specifics ?? {};
    const instructions = req.instructions ?? [];
    const history = req.history ?? [];
    const t = norm(req.text);
    const quote = `Message reçu : « ${clip(req.text)} ».`;
    const recentClient = history
        .filter((m) => m.author === "client")
        .slice(-4)
        .map((m) => m.text);
    const recentClientNorm = norm(recentClient.join(" "));
    const lastAssistant = norm([...history].reverse().find((m) => m.author === "assistant")?.text ?? "");
    const bookingInProgress = BOOKING_QUESTION.test(lastAssistant);
    // ── 1. Réclamation : toujours transmise, jamais discutée ──
    if (has(t, COMPLAINT)) {
        return escalate("Un client fait une réclamation.", quote, "Je suis désolé de l'apprendre. Je transmets votre message au restaurant, qui revient vers vous personnellement très vite.", "Réclamation d'un client : transmise au restaurant.");
    }
    // ── Prix : jamais de chiffre inventé, la demande est transmise ──
    if (asksPrice(t)) {
        return escalate("Un client demande un prix.", quote, "Je transmets votre question au restaurant, qui vous répond très vite.", "Question de prix : transmise au restaurant.");
    }
    // ── 2. Annulation ──
    if (has(t, CANCEL)) {
        return escalate("Un client annule sa réservation.", quote, "C'est noté, je transmets l'annulation au restaurant. Merci de nous avoir prévenus !", "Annulation de réservation : transmise au restaurant.");
    }
    // ── 3. Modification d'une réservation existante ──
    if (has(t, MOVE)) {
        const slot = parseSlot(req.text, now);
        const size = partySize(t);
        const wish = [
            slot.day ? `${humanDay(slot.day)}${slot.time ? ` à ${humanTime(slot.time)}` : ""}` : "",
            size ? `${size} personne${size > 1 ? "s" : ""}` : "",
        ].filter(Boolean);
        return escalate("Un client veut modifier sa réservation.", `${quote}${wish.length ? ` Souhait : ${wish.join(", ")}.` : ""}`, "C'est noté. Je transmets votre demande au restaurant, qui vous confirme la modification très vite.", "Modification de réservation : transmise au restaurant.");
    }
    // ── 4. Liste d'attente ──
    if (has(t, WAITLIST)) {
        return escalate("Un client souhaite être prévenu si une table se libère.", quote, "C'est noté : je transmets votre demande au restaurant, qui vous prévient si une table se libère.", "Demande de liste d'attente : transmise au restaurant.");
    }
    // ── 5. Privatisation, événement : le patron décide ──
    if (has(t, PRIVATE_EVENT)) {
        return escalate("Une demande de privatisation ou d'événement.", quote, "Avec plaisir ! Je transmets votre demande au restaurant, qui vous recontacte pour en parler.", "Demande d'événement ou de privatisation : transmise au restaurant.");
    }
    // ── 6. Le nom de la réservation, quand il vient de le demander ──
    if (ASKED_NAME.test(lastAssistant)) {
        const name = cleanName(req.text);
        if (name) {
            return reply(`Merci, c'est noté au nom de ${name}. Le restaurant vous confirme la réservation très vite.`, `Réservation notée au nom de ${name}, à confirmer.`, "rendez_vous");
        }
    }
    // ── 7. Réservation ──
    const slotHere = parseSlot(req.text, now);
    const sizeHere = partySize(t) ?? (bookingInProgress ? bareNumber(t) : null);
    const wantsBooking = has(t, BOOK) ||
        (bookingInProgress &&
            !has(t, HOURS) &&
            !asksAddress(t) &&
            !has(t, MENU) &&
            Boolean(slotHere.day || slotHere.time || slotHere.part || sizeHere));
    if (wantsBooking) {
        return booking(req, now, { t, quote, recentClient, recentClientNorm, lastAssistant, slotHere, sizeHere });
    }
    // ── 8. Allergies, régimes : jamais de garantie, sauf consigne du patron ──
    if (has(t, ALLERGY)) {
        const matched = matchInstruction(instructions, req.text);
        if (matched) {
            return reply(`${sentence(matched)} Pensez à signaler toute allergie en arrivant, l'équipe en cuisine vérifiera pour vous.`, "Question sur un régime ou une allergie : réponse donnée grâce à une de vos consignes.");
        }
        return escalate("Un client pose une question sur une allergie ou un régime alimentaire.", quote, "Je préfère que la cuisine vous réponde elle-même sur ce point : je transmets votre question au restaurant, qui vous répond très vite.", "Question sur une allergie ou un régime : transmise au restaurant.");
    }
    // ── 9. Horaires ──
    if (has(t, HOURS)) {
        const hours = sp.horaires?.trim() || a.establishment?.openingHours || a.jobDescription?.hours;
        if (hours) {
            const extra = instructions.find((i) => /ferm|vacances|cong|horaire/i.test(i));
            return reply(`Nos horaires de service : ${hours}.${extra ? ` ${sentence(extra)}` : ""}`, "Horaires donnés à un client.");
        }
        return escalate("Un client demande les horaires, qui ne sont pas renseignés.", quote, "Je vérifie les horaires et je reviens vers vous très vite.", "Question sur les horaires : transmise au restaurant.");
    }
    // ── 10. Adresse, accès, stationnement ──
    if (asksAddress(t)) {
        const addr = a.establishment?.address;
        const access = instructions.find((i) => /parking|acc[eè]s|stationn|m[ée]tro|bus|tram|venir/i.test(i)) ?? null;
        if (addr) {
            return reply(`Le restaurant se trouve au ${addr}.${access ? ` ${sentence(access)}` : ""}`, "Adresse donnée à un client.");
        }
